import itertools

names = ["Peter", "Eric", "Alice", "Arnold"]
smoothies = ["watermelon", "desert", "cherry", "dragonfruit"]
colors = ["green", "white", "red", "yellow"]

def satisfies(name_perm, smooth_perm, color_perm):
    # Helper to get house index (0‑based) of a given attribute
    def house_of_name(n):
        return name_perm.index(n)
    def house_of_smooth(s):
        return smooth_perm.index(s)
    def house_of_color(c):
        return color_perm.index(c)

    # 1. Dragonfruit lover is Eric
    if name_perm[house_of_smooth("dragonfruit")] != "Eric":
        return False
    # 2. House 2 smoothie is cherry
    if smooth_perm[1] != "cherry":
        return False
    # 3. House 4 smoothie is dragonfruit
    if smooth_perm[3] != "dragonfruit":
        return False
    # 4. Arnold's smoothie is watermelon
    if smooth_perm[house_of_name("Arnold")] != "watermelon":
        return False
    # 5. House 1 color is white
    if color_perm[0] != "white":
        return False
    # 6. Peter's color is white
    if color_perm[house_of_name("Peter")] != "white":
        return False
    # 7. Yellow lover has watermelon smoothie
    if smooth_perm[house_of_color("yellow")] != "watermelon":
        return False
    # 8. Dragonfruit lover's color is red
    if color_perm[house_of_smooth("dragonfruit")] != "red":
        return False

    return True

solution = None
for name_perm in itertools.permutations(names):
    for smooth_perm in itertools.permutations(smoothies):
        for color_perm in itertools.permutations(colors):
            if satisfies(name_perm, smooth_perm, color_perm):
                solution = (name_perm, smooth_perm, color_perm)
                break
        if solution:
            break
    if solution:
        break

if solution is None:
    raise RuntimeError("No solution found")

name_perm, smooth_perm, color_perm = solution
for i in range(4):
    print(f"House {i+1}: {name_perm[i]}, {smooth_perm[i]}, {color_perm[i]}")

import itertools

houses = [1, 2, 3]

names = ["Eric", "Arnold", "Peter"]
cars = ["ford f150", "tesla model 3", "toyota camry"]
vacations = ["beach", "mountain", "city"]
nationalities = ["dane", "swede", "brit"]
hairs = ["blonde", "black", "brown"]
styles = ["colonial", "ranch", "victorian"]

def solve():
    for perm_name in itertools.permutations(names):
        name_by_house = dict(zip(houses, perm_name))

        # Helper look‑ups for this level
        def house_of_name(val):
            return next(h for h, n in name_by_house.items() if n == val)

        for perm_nat in itertools.permutations(nationalities):
            nat_by_house = dict(zip(houses, perm_nat))

            def house_of_nat(val):
                return next(h for h, n in nat_by_house.items() if n == val)

            # clue 5 & 10 involve nationality & hair later, keep for now
            for perm_car in itertools.permutations(cars):
                car_by_house = dict(zip(houses, perm_car))

                def house_of_car(val):
                    return next(h for h, c in car_by_house.items() if c == val)

                for perm_vac in itertools.permutations(vacations):
                    vac_by_house = dict(zip(houses, perm_vac))

                    def house_of_vac(val):
                        return next(h for h, v in vac_by_house.items() if v == val)

                    for perm_hair in itertools.permutations(hairs):
                        hair_by_house = dict(zip(houses, perm_hair))

                        def house_of_hair(val):
                            return next(h for h, ha in hair_by_house.items() if ha == val)

                        for perm_style in itertools.permutations(styles):
                            style_by_house = dict(zip(houses, perm_style))

                            def house_of_style(val):
                                return next(h for h, s in style_by_house.items() if s == val)

                            # ----- evaluate clues -----
                            # 1. Swedish person owns a Ford F-150.
                            if house_of_nat("swede") != house_of_car("ford f150"):
                                continue
                            # 2. Blonde hair is not in the second house.
                            if house_of_hair("blonde") == 2:
                                continue
                            # 3. Toyota Camry owner and Arnold are next to each other.
                            if abs(house_of_car("toyota camry") - house_of_name("Arnold")) != 1:
                                continue
                            # 4. Black hair is somewhere to the right of the ranch house.
                            if house_of_hair("black") <= house_of_style("ranch"):
                                continue
                            # 5. Black hair is the Dane.
                            if house_of_hair("black") != house_of_nat("dane"):
                                continue
                            # 6. Victorian house is not in the second house.
                            if house_of_style("victorian") == 2:
                                continue
                            # 7. Peter is directly left of the beach‑vacation lover.
                            if house_of_vac("beach") != house_of_name("Peter") + 1:
                                continue
                            # 8. Colonial house style belongs to the blonde‑haired person.
                            if house_of_style("colonial") != house_of_hair("blonde"):
                                continue
                            # 9. Black hair is Arnold.
                            if house_of_hair("black") != house_of_name("Arnold"):
                                continue
                            #10. Dane loves beach vacations.
                            if house_of_vac("beach") != house_of_nat("dane"):
                                continue
                            #11. Peter prefers city vacations.
                            if house_of_vac("city") != house_of_name("Peter"):
                                continue

                            # All clues satisfied – print solution
                            for h in houses:
                                print(
                                    f"House {h}: "
                                    f"{name_by_house[h]}, "
                                    f"{car_by_house[h]}, "
                                    f"{vac_by_house[h]}, "
                                    f"{nat_by_house[h]}, "
                                    f"{hair_by_house[h]}, "
                                    f"{style_by_house[h]}"
                                )
                            return

if __name__ == "__main__":
    solve()

import itertools

names = ['Bob', 'Alice', 'Eric', 'Arnold', 'Peter']
mothers = ['Aniya', 'Janelle', 'Penny', 'Kailyn', 'Holly']
musics = ['pop', 'jazz', 'rock', 'classical', 'hip hop']
lunches = ['grilled cheese', 'stir fry', 'stew', 'spaghetti', 'pizza']

def solve():
    # generate all permutations for each category
    for name_perm in itertools.permutations(names):
        # quick check for fixed clues involving names
        # clue 4: Peter loves stir fry (handled later)
        # clue 5: Alice loves spaghetti (handled later)
        # clue 12: Arnold loves pop (handled later)
        name_idx = {n: i for i, n in enumerate(name_perm)}

        for mother_perm in itertools.permutations(mothers):
            mother_idx = {m: i for i, m in enumerate(mother_perm)}

            # clue 3: mother Penny directly left of Alice
            if mother_idx['Penny'] + 1 != name_idx['Alice']:
                continue
            # clue 7: Kailyn directly left of Aniya
            if mother_idx['Kailyn'] + 1 != mother_idx['Aniya']:
                continue
            # clue 10: pop music person has mother Kailyn (handled after music)

            for music_perm in itertools.permutations(musics):
                music_idx = {m: i for i, m in enumerate(music_perm)}

                # clue 1: Eric left of classical
                if name_idx['Eric'] >= music_idx['classical']:
                    continue
                # clue 6: Eric left of rock
                if name_idx['Eric'] >= music_idx['rock']:
                    continue
                # clue 8: rock not in third house (index 2)
                if music_idx['rock'] == 2:
                    continue
                # clue 12: Arnold loves pop
                if name_idx['Arnold'] != music_idx['pop']:
                    continue
                # clue 10: pop music person has mother Kailyn
                if mother_idx['Kailyn'] != music_idx['pop']:
                    continue
                # clue 11: spaghetti eater is jazz music (handled after lunch)

                for lunch_perm in itertools.permutations(lunches):
                    lunch_idx = {l: i for i, l in enumerate(lunch_perm)}

                    # clue 2: grilled cheese directly left of mother Janelle
                    if lunch_idx['grilled cheese'] + 1 != mother_idx['Janelle']:
                        continue
                    # clue 9: grilled cheese directly left of stew
                    if lunch_idx['grilled cheese'] + 1 != lunch_idx['stew']:
                        continue
                    # clue 4: Peter loves stir fry
                    if name_idx['Peter'] != lunch_idx['stir fry']:
                        continue
                    # clue 5: Alice loves spaghetti
                    if name_idx['Alice'] != lunch_idx['spaghetti']:
                        continue
                    # clue 11: spaghetti eater is jazz music
                    if lunch_idx['spaghetti'] != music_idx['jazz']:
                        continue

                    # All constraints satisfied; build solution
                    solution = []
                    for house in range(5):
                        sol = (
                            name_perm[house],
                            mother_perm[house],
                            music_perm[house],
                            lunch_perm[house]
                        )
                        solution.append(sol)

                    # print in required format
                    for i, (nm, mt, mu, lt) in enumerate(solution, start=1):
                        print(f"House {i}: {nm}, {mt}, {mu}, {lt}")
                    return

    # if no solution found
    print("No solution")

if __name__ == "__main__":
    solve()

#!/usr/bin/env python3
import itertools
import sys

# ----- data ---------------------------------------------------------

names   = ["Peter", "Arnold", "Eric", "Carol", "Alice", "Bob"]
musics  = ["country", "classical", "pop", "hip hop", "jazz", "rock"]
styles  = ["modern", "mediterranean", "victorian", "craftsman", "ranch", "colonial"]
phones  = ["huawei p50", "iphone 13", "google pixel 6", "oneplus 9",
           "xiaomi mi 11", "samsung galaxy s21"]
pets    = ["hamster", "dog", "cat", "rabbit", "fish", "bird"]

# fixed information derived directly from clues
fixed = {
    2: {"name": "Peter", "style": "colonial", "phone": "oneplus 9", "music": "rock"},
    5: {"pet": "dog"},
    6: {"pet": "rabbit"},
    1: {"music": "pop"},
}

# ----- helper functions ----------------------------------------------

def adjacent(a, b):
    return abs(a - b) == 1

def left_of(a, b):
    return a < b

def right_of(a, b):
    return a > b

# check all clues on a *complete* assignment
def check_all(houses):
    # helper: locate house index by attribute value
    def locate(attr, val):
        for i, h in enumerate(houses, start=1):
            if h.get(attr) == val:
                return i
        return None

    # 1. cat -> mediterranean
    cat_house = locate("pet", "cat")
    if cat_house is not None:
        if houses[cat_house-1].get("style") != "mediterranean":
            return False
        if cat_house == 4:                     # 21. cat not in fourth house
            return False

    # 2. Peter is house 2 – already enforced by fixed data
    # 3. modern style -> Samsung phone – enforced while assigning
    # 4. bird -> Google Pixel 6
    bird_house = locate("pet", "bird")
    if bird_house is not None:
        if houses[bird_house-1].get("phone") != "google pixel 6":
            return False

    # 5. bird directly left of Xiaomi phone
    if bird_house is not None:
        xiaomi_house = locate("phone", "xiaomi mi 11")
        if xiaomi_house is not None:
            if not left_of(bird_house, xiaomi_house) or xiaomi_house - bird_house != 1:
                return False

    # 6. Arnold Victorian
    arnold_house = locate("name", "Arnold")
    if arnold_house is not None:
        if houses[arnold_house-1].get("style") != "victorian":
            return False

    # 7. rock music -> colonial style – already satisfied for Peter
    # 8. Craftsman style -> Carol
    crafts_house = locate("style", "craftsman")
    if crafts_house is not None:
        if houses[crafts_house-1].get("name") != "Carol":
            return False

    # 9. rabbit in sixth house – enforced by fixed
    #10. pop left of colonial (colonial is house 2)
    pop_house = locate("music", "pop")
    if pop_house is not None and not left_of(pop_house, 2):
        return False

    #11. Huawei P50 next to country music
    huawei_house = locate("phone", "huawei p50")
    country_house = locate("music", "country")
    if huawei_house is not None and country_house is not None:
        if not adjacent(huawei_house, country_house):
            return False

    #12. hip hop -> Samsung
    hiphop_house = locate("music", "hip hop")
    if hiphop_house is not None:
        if houses[hiphop_house-1].get("phone") != "samsung galaxy s21":
            return False

    #13. Carol and Peter adjacent
    carol_house = locate("name", "Carol")
    if carol_house is not None and not adjacent(carol_house, 2):
        return False

    #14. Peter phone OnePlus 9 – fixed
    #15. hamster not in first house
    if houses[0].get("pet") == "hamster":
        return False

    #16. ranch left of classical music
    ranch_house = locate("style", "ranch")
    classical_house = locate("music", "classical")
    if ranch_house is not None and classical_house is not None:
        if not left_of(ranch_house, classical_house):
            return False

    #17. two houses between Carol and Alice (distance 3)
    alice_house = locate("name", "Alice")
    if carol_house is not None and alice_house is not None:
        if abs(carol_house - alice_house) != 3:
            return False

    #18. dog in fifth house – fixed
    #19. modern style -> Eric – enforced while assigning
    #20. Peter colonial – fixed
    #21. cat not in fourth – already checked

    return True

# ----- backtracking search -------------------------------------------

def solve():
    # remaining values for each category
    rem = {
        "name": set(names),
        "music": set(musics),
        "style": set(styles),
        "phone": set(phones),
        "pet": set(pets),
    }

    # apply fixed data to the remaining sets
    for h, attrs in fixed.items():
        for k, v in attrs.items():
            rem[k].discard(v)

    houses = [{} for _ in range(6)]

    def backtrack(idx):
        if idx == 6:                     # all houses assigned
            if check_all(houses):
                return True
            return False

        house_no = idx + 1
        fixed_attrs = fixed.get(house_no, {})

        # generate possible values for each category respecting fixed data
        possible_names = [fixed_attrs["name"]] if "name" in fixed_attrs else list(rem["name"])
        possible_musics = [fixed_attrs["music"]] if "music" in fixed_attrs else list(rem["music"])
        possible_styles = [fixed_attrs["style"]] if "style" in fixed_attrs else list(rem["style"])
        possible_phones = [fixed_attrs["phone"]] if "phone" in fixed_attrs else list(rem["phone"])
        possible_pets = [fixed_attrs["pet"]] if "pet" in fixed_attrs else list(rem["pet"])

        # iterate over combinations – the order is chosen to prune early
        for name in possible_names:
            # name‑specific deductions
            style_req = None
            phone_req = None
            music_req = None
            if name == "Eric":
                style_req = "modern"
                phone_req = "samsung galaxy s21"
                music_req = "hip hop"
            if name == "Carol":
                style_req = "craftsman"
            # apply style requirement if present
            styles_iter = [style_req] if style_req else possible_styles
            for style in styles_iter:
                if style not in possible_styles:
                    continue
                # name‑style consistency (e.g., Carol must be craftsman)
                if name == "Carol" and style != "craftsman":
                    continue
                if name == "Eric" and style != "modern":
                    continue
                # adjacency rule for Carol & Peter
                if name == "Carol":
                    if not adjacent(house_no, 2):
                        continue
                # Arnold Victorian rule
                if name == "Arnold" and style != "victorian":
                    continue
                # Peter already fixed, will be handled by fixed_attrs

                # phones dependent on style/name
                phones_iter = [phone_req] if phone_req else possible_phones
                for phone in phones_iter:
                    if phone not in possible_phones:
                        continue
                    # modern -> Samsung (already covered by Eric)
                    if style == "modern" and phone != "samsung galaxy s21":
                        continue
                    if phone == "samsung galaxy s21" and style != "modern":
                        continue
                    # hip‑hop -> Samsung (already covered)
                    if music_req == "hip hop" and phone != "samsung galaxy s21":
                        continue
                    if phone == "samsung galaxy s21" and music_req and music_req != "hip hop":
                        continue

                    musics_iter = [music_req] if music_req else possible_musics
                    for music in musics_iter:
                        if music not in possible_musics:
                            continue
                        # rock -> colonial (Peter already satisfies)
                        if music == "rock" and style != "colonial":
                            continue
                        if style == "colonial" and music != "rock":
                            # only Peter has colonial, already fixed; other houses cannot be colonial
                            continue
                        # pop left of colonial already enforced by fixed house 1 music pop
                        # other positional constraints will be checked later

                        for pet in possible_pets:
                            if pet not in possible_pets:
                                continue
                            # cat -> mediterranean
                            if pet == "cat" and style != "mediterranean":
                                continue
                            if style == "mediterranean" and pet != "cat":
                                continue
                            # hamster not in first house
                            if house_no == 1 and pet == "hamster":
                                continue
                            # bird -> Google Pixel 6
                            if pet == "bird" and phone != "google pixel 6":
                                continue
                            if phone == "google pixel 6" and pet != "bird":
                                continue
                            # dog fixed house5 already handled by fixed_attrs
                            # rabbit fixed house6 already handled

                            # all local constraints satisfied – commit this choice
                            houses[idx] = {
                                "name": name,
                                "music": music,
                                "style": style,
                                "phone": phone,
                                "pet": pet,
                            }
                            # remove used values from remaining sets
                            for cat, val in (("name", name), ("music", music),
                                             ("style", style), ("phone", phone),
                                             ("pet", pet)):
                                rem[cat].remove(val)
                            # recurse
                            if backtrack(idx + 1):
                                return True
                            # backtrack: restore sets
                            for cat, val in (("name", name), ("music", music),
                                             ("style", style), ("phone", phone),
                                             ("pet", pet)):
                                rem[cat].add(val)
        return False

    if not backtrack(0):
        sys.exit("No solution found")

    # ----- output ----------------------------------------------------
    for i, h in enumerate(houses, start=1):
        print(f"House {i}: {h['name']}, {h['music']}, {h['style']}, {h['phone']}, {h['pet']}")

if __name__ == "__main__":
    solve()

import itertools

names = ['Peter', 'Eric', 'Arnold', 'Alice', 'Bob']
phones = ['Google Pixel 6', 'Samsung Galaxy S21', 'Huawei P50', 'OnePlus 9', 'iPhone 13']

def solve():
    for name_perm in itertools.permutations(names):
        # Constraint 2: Alice is in house 5 (index 4)
        if name_perm[4] != 'Alice':
            continue
        for phone_perm in itertools.permutations(phones):
            # Constraint 7: Huawei P50 is in house 1 (index 0)
            if phone_perm[0] != 'Huawei P50':
                continue

            # Helper look‑ups
            idx_name = {n: i for i, n in enumerate(name_perm)}
            idx_phone = {p: i for i, p in enumerate(phone_perm)}

            # 1. Eric uses Samsung Galaxy S21
            if phone_perm[idx_name['Eric']] != 'Samsung Galaxy S21':
                continue
            # 5. Bob uses Huawei P50
            if phone_perm[idx_name['Bob']] != 'Huawei P50':
                continue
            # 3. Samsung left of Google Pixel 6
            if idx_phone['Samsung Galaxy S21'] >= idx_phone['Google Pixel 6']:
                continue
            # 4. Arnold directly left of OnePlus 9
            if idx_name['Arnold'] + 1 != idx_phone['OnePlus 9']:
                continue
            # 6. iPhone 13 directly left of OnePlus 9
            if idx_phone['iPhone 13'] + 1 != idx_phone['OnePlus 9']:
                continue
            # 8. Google Pixel 6 left of OnePlus 9
            if idx_phone['Google Pixel 6'] >= idx_phone['OnePlus 9']:
                continue

            # All constraints satisfied – print solution
            for house in range(5):
