import itertools

houses = [1, 2]
names = ['Eric', 'Arnold']
phones = ['iphone 13', 'samsung galaxy s21']
drinks = ['water', 'tea']
sports = ['basketball', 'soccer']

def satisfies(solution):
    # solution is a dict: house -> {'name':..., 'phone':..., 'drink':..., 'sport':...}
    # Constraint 1: Arnold is in house 2
    if solution[2]['name'] != 'Arnold':
        return False
    # Constraint 2: Samsung Galaxy S21 is not in house 1
    if solution[1]['phone'] == 'samsung galaxy s21':
        return False
    # Constraint 3: Eric loves soccer
    eric_house = next(h for h, attrs in solution.items() if attrs['name'] == 'Eric')
    if solution[eric_house]['sport'] != 'soccer':
        return False
    # Constraint 4: Samsung user drinks tea
    for attrs in solution.values():
        if attrs['phone'] == 'samsung galaxy s21' and attrs['drink'] != 'tea':
            return False
    return True

# Generate all permutations for each attribute across the two houses
for name_perm in itertools.permutations(names):
    for phone_perm in itertools.permutations(phones):
        for drink_perm in itertools.permutations(drinks):
            for sport_perm in itertools.permutations(sports):
                solution = {
                    1: {'name': name_perm[0], 'phone': phone_perm[0],
                        'drink': drink_perm[0], 'sport': sport_perm[0]},
                    2: {'name': name_perm[1], 'phone': phone_perm[1],
                        'drink': drink_perm[1], 'sport': sport_perm[1]},
                }
                if satisfies(solution):
                    for house in sorted(solution):
                        attrs = solution[house]
                        print(f"House {house}: {attrs['name']}, {attrs['phone']}, {attrs['drink']}, {attrs['sport']}")
                    raise SystemExit

import itertools
import sys

names = ['Bob', 'Carol', 'Eric', 'Alice', 'Peter', 'Arnold']
vacations = ['camping', 'cruise', 'mountain', 'cultural', 'city', 'beach']
pets = ['fish', 'hamster', 'bird', 'rabbit', 'dog', 'cat']
nationalities = ['brit', 'swede', 'german', 'norwegian', 'dane', 'chinese']
books = ['biography', 'romance', 'mystery', 'fantasy', 'science fiction', 'historical fiction']
cars = ['tesla model 3', 'bmw 3 series', 'honda civic', 'chevrolet silverado', 'toyota camry', 'ford f150']

# Helper to get index of a value in a permutation
def idx(perm, value):
    return perm.index(value)

for name_perm in itertools.permutations(names):
    # 24. The Dane is Bob → later when nationalities are known
    # 27. Eric is not in the third house
    if name_perm[2] == 'Eric':
        continue
    # 13. Eric is not in the sixth house
    if name_perm[5] == 'Eric':
        continue

    for car_perm in itertools.permutations(cars):
        # 7. Honda Civic is in the first house
        if car_perm[0] != 'honda civic':
            continue
        # 9. British person owns a Honda Civic → later when nationalities are known
        # 20. German owns a BMW 3 series → later
        # 10. One house between fantasy book and Toyota Camry → later (needs books)
        # 11. Bird pet owner has Toyota Camry → later (needs pets)
        # 3. Tesla Model 3 owner has hamster → later (needs pets)
        # 18. Ford F-150 owner has rabbit → later (needs pets)

        for pet_perm in itertools.permutations(pets):
            # 5. Cat is in the second house
            if pet_perm[1] != 'cat':
                continue
            # 16. Dog is in the fifth house
            if pet_perm[4] != 'dog':
                continue
            # 3. Tesla Model 3 owner has hamster
            if pet_perm[idx(car_perm, 'tesla model 3')] != 'hamster':
                continue
            # 11. Bird pet owner has Toyota Camry
            if pet_perm[idx(car_perm, 'toyota camry')] != 'bird':
                continue
            # 18. Ford F-150 owner has rabbit
            if pet_perm[idx(car_perm, 'ford f150')] != 'rabbit':
                continue

            for nat_perm in itertools.permutations(nationalities):
                # 2. Chinese is somewhere to the right of the Dane
                if idx(nat_perm, 'chinese') <= idx(nat_perm, 'dane'):
                    continue
                # 12. Dane is not in the third house
                if idx(nat_perm, 'dane') == 2:
                    continue
                # 24. The Dane is Bob
                if name_perm[idx(nat_perm, 'dane')] != 'Bob':
                    continue
                # 9. British person owns a Honda Civic
                if nat_perm[idx(car_perm, 'honda civic')] != 'brit':
                    continue
                # 20. German owns a BMW 3 series
                if nat_perm[idx(car_perm, 'bmw 3 series')] != 'german':
                    continue
                # 26. Swedish person is somewhere to the right of the person who likes cruises (Arnold)
                if idx(nat_perm, 'swede') <= idx(name_perm, 'Arnold'):
                    continue
                # 25. One house between the Dane and the Chinese
                if abs(idx(nat_perm, 'dane') - idx(nat_perm, 'chinese')) != 2:
                    continue

                for vac_perm in itertools.permutations(vacations):
                    # 4. Carol loves beach vacations
                    if vac_perm[idx(name_perm, 'Carol')] != 'beach':
                        continue
                    # 15. Arnold likes cruises
                    if vac_perm[idx(name_perm, 'Arnold')] != 'cruise':
                        continue
                    # 17. Camping is directly left of rabbit owner
                    if idx(vac_perm, 'camping') != idx(pet_perm, 'rabbit') - 1:
                        continue
                    # 21. Cultural tours not in the first house
