import sys

names = ['Peter', 'Alice', 'Eric', 'Arnold']
hobbies = ['cooking', 'painting', 'gardening', 'photography']
animals = ['horse', 'fish', 'cat', 'bird']
books = ['fantasy', 'mystery', 'romance', 'science fiction']
months = ['april', 'jan', 'sept', 'feb']
musics = ['pop', 'rock', 'classical', 'jazz']

# Helper to check all constraints given a partial assignment
def consistent(houses, idx):
    # houses: list of dicts (or None) length 4, each dict may have missing keys
    # idx: last filled house index (0‑based)
    # Build lookup tables for attributes that are already assigned
    pos_name = {}
    pos_hobby = {}
    pos_animal = {}
    pos_book = {}
    pos_month = {}
    pos_music = {}
    for i, h in enumerate(houses):
        if h is None:
            continue
        for k, v in h.items():
            if k == 'name':   pos_name[v] = i
            if k == 'hobby':  pos_hobby[v] = i
            if k == 'animal': pos_animal[v] = i
            if k == 'book':   pos_book[v] = i
            if k == 'month':  pos_month[v] = i
            if k == 'music':  pos_music[v] = i

    # 1. cooking hobby == romance book
    if 'cooking' in pos_hobby and 'romance' in pos_book:
        if pos_hobby['cooking'] != pos_book['romance']:
            return False
    # 2. feb month == pop music
    if 'feb' in pos_month and 'pop' in pos_music:
        if pos_month['feb'] != pos_music['pop']:
            return False
    # 5. feb month == fish animal
    if 'feb' in pos_month and 'fish' in pos_animal:
        if pos_month['feb'] != pos_animal['fish']:
            return False
    # 8. gardening hobby == april month
    if 'gardening' in pos_hobby and 'april' in pos_month:
        if pos_hobby['gardening'] != pos_month['april']:
            return False
    # 9. jazz music == cooking hobby
    if 'jazz' in pos_music and 'cooking' in pos_hobby:
        if pos_music['jazz'] != pos_hobby['cooking']:
            return False
    #10. rock music == mystery book
    if 'rock' in pos_music and 'mystery' in pos_book:
        if pos_music['rock'] != pos_book['mystery']:
            return False
    #7. horse animal == rock music
    if 'horse' in pos_animal and 'rock' in pos_music:
        if pos_animal['horse'] != pos_music['rock']:
            return False
    #12. Peter == pop music
    if 'Peter' in pos_name and 'pop' in pos_music:
        if pos_name['Peter'] != pos_music['pop']:
            return False
    #13. Arnold's hobby is gardening
    if 'Arnold' in pos_name and 'gardening' in pos_hobby:
        if pos_name['Arnold'] != pos_hobby['gardening']:
            return False
    #3. Eric not in house 2 (index 1)
    if 'Eric' in pos_name and pos_name['Eric'] == 1:
        return False
    #4. romance book not in house 4 (index 3)
    if 'romance' in pos_book and pos_book['romance'] == 3:
        return False
    #15. cooking hobby not in house 3 (index 2)
    if 'cooking' in pos_hobby and pos_hobby['cooking'] == 2:
        return False
    #11. painting hobby directly left of romance book
    if 'painting' in pos_hobby and 'romance' in pos_book:
        if pos_hobby['painting'] + 1 != pos_book['romance']:
            return False
    #14. rock music directly left of january month
    if 'rock' in pos_music and 'jan' in pos_month:
        if pos_music['rock'] + 1 != pos_month['jan']:
            return False
    #6. Alice somewhere to the right of fantasy book
    if 'Alice' in pos_name and 'fantasy' in pos_book:
        if pos_name['Alice'] <= pos_book['fantasy']:
            return False
    #16. cat animal somewhere to the right of horse animal
    if 'cat' in pos_animal and 'horse' in pos_animal:
        if pos_animal['cat'] <= pos_animal['horse']:
            return False
    return True

def solve():
    houses = [None] * 4
    remaining = {
        'name': set(names),
        'hobby': set(hobbies),
        'animal': set(animals),
        'book': set(books),
        'month': set(months),
        'music': set(musics)
    }

    def backtrack(i):
        if i == 4:
            # final consistency check (all constraints should hold)
            if consistent(houses, 3):
                return True
            return False
        # iterate over possible values respecting simple forced links
        for name in list(remaining['name']):
            # early prune for Peter (must be pop music) and Arnold (must be gardening)
            if name == 'Peter' and 'pop' not in remaining['music']:
                continue
            if name == 'Arnold' and 'gardening' not in remaining['hobby']:
                continue
            for hobby in list(remaining['hobby']):
                # Arnold must have gardening
                if name == 'Arnold' and hobby != 'gardening':
                    continue
                if hobby == 'gardening' and name != 'Arnold':
                    continue
                # cooking hobby forces romance book, jazz music
                if hobby == 'cooking':
                    if 'romance' not in remaining['book']:
                        continue
                    if 'jazz' not in remaining['music']:
                        continue
                # painting hobby will need romance book to the right; can't be last house
                if hobby == 'painting' and i == 3:
                    continue
                # gardening hobby forces april month
                if hobby == 'gardening' and 'april' not in remaining['month']:
                    continue
                for animal in list(remaining['animal']):
                    # horse animal forces rock music
                    if animal == 'horse' and 'rock' not in remaining['music']:
                        continue
                    # fish animal forces feb month
                    if animal == 'fish' and 'feb' not in remaining['month']:
                        continue
                    for book in list(remaining['book']):
                        # cooking hobby forces romance book
                        if hobby == 'cooking' and book != 'romance':
                            continue
                        # romance book cannot be house 4 (handled later)
                        # painting hobby left of romance handled later
                        # rock music forces mystery book (handled later)
                        for month in list(remaining['month']):
                            # gardening hobby forces april month
                            if hobby == 'gardening' and month != 'april':
                                continue
                            # feb month forces pop music and fish animal
                            if month == 'feb' and ('pop' not in remaining['music'] or 'fish' not in remaining['animal']):
                                continue
                            for music in list(remaining['music']):
                                # pop music forces feb month
                                if music == 'pop' and month != 'feb':
                                    continue
                                # jazz music forces cooking hobby
                                if music == 'jazz' and hobby != 'cooking':
                                    continue
                                # rock music forces horse animal and mystery book
                                if music == 'rock':
                                    if animal != 'horse':
                                        continue
                                    if 'mystery' not in remaining['book'] and book != 'mystery':
                                        continue
                                    if book != 'mystery':
                                        continue
                                # pop music forces Peter name
                                if music == 'pop' and name != 'Peter':
                                    continue
                                # rock music left of jan month
                                if music == 'rock' and month == 'jan':
                                    # rock cannot be same house as jan
                                    continue
                                # assign
                                houses[i] = {
                                    'name': name,
                                    'hobby': hobby,
                                    'animal': animal,
                                    'book': book,
                                    'month': month,
                                    'music': music
                                }
                                # remove from remaining
                                for cat, val in [('name', name), ('hobby', hobby), ('animal', animal),
                                                 ('book', book), ('month', month), ('music', music)]:
                                    remaining[cat].remove(val)
                                if consistent(houses, i):
                                    if backtrack(i + 1):
                                        return True
                                # backtrack restore
                                for cat, val in [('name', name), ('hobby', hobby), ('animal', animal),
                                                 ('book', book), ('month', month), ('music', music)]:
                                    remaining[cat].add(val)
                                houses[i] = None
        return False

    if backtrack(0):
        for idx, h in enumerate(houses, start=1):
            print(f"House {idx}: {h['name']}, {h['hobby']}, {h['animal']}, {h['book']}, {h['month']}, {h['music']}")
    else:
        print("No solution found", file=sys.stderr)

if __name__ == "__main__":
    solve()

