import itertools

houses = [1, 2, 3, 4]

names = ["Peter", "Eric", "Arnold", "Alice"]
musics = ["jazz", "rock", "classical", "pop"]

def satisfies(names_at, music_at):
    # Helper to find house index (1‑based) of a given name or music
    def house_of_name(name):
        return names_at.index(name) + 1
    def house_of_music(music):
        return music_at.index(music) + 1

    # 1. Alice is directly left of Peter.
    if house_of_name("Alice") != house_of_name("Peter") - 1:
        return False

    # 2. The person who loves classical music is directly left of Peter.
    if house_of_music("classical") != house_of_name("Peter") - 1:
        return False

    # 3. Arnold is the person who loves jazz music.
    if house_of_name("Arnold") != house_of_music("jazz"):
        return False

    # 4. The person who loves rock music is not in the second house.
    if house_of_music("rock") == 2:
        return False

    # 5. The person who loves rock music is directly left of the person who loves pop music.
    if house_of_music("rock") != house_of_music("pop") - 1:
        return False

    return True

solution = None
for names_perm in itertools.permutations(names):
    for music_perm in itertools.permutations(musics):
        if satisfies(names_perm, music_perm):
            solution = (names_perm, music_perm)
            break
    if solution:
        break

if solution is None:
