#!/usr/bin/env python3
import itertools
import sys

# ----- Data -----
names = ["Eric", "Alice", "Arnold", "Peter", "Bob"]
phones = [
    "samsung galaxy s21",
    "huawei p50",
    "oneplus 9",
    "iphone 13",
    "google pixel 6",
]
smoothies = ["desert", "dragonfruit", "watermelon", "cherry", "lime"]
mothers = ["Janelle", "Holly", "Penny", "Aniya", "Kailyn"]
occupations = ["doctor", "lawyer", "engineer", "teacher", "artist"]

# ----- Helper to check constraints that involve already placed houses -----
def consistent(state, house):
    """state holds dicts: name, phone, smoothie, mother, occ keyed by house number."""
    n = state["name"].get(house)
    p = state["phone"].get(house)
    s = state["smoothie"].get(house)
    m = state["mother"].get(house)
    o = state["occ"].get(house)

    # 1. mother Kailyn is Peter
    if n == "Peter" and m != "Kailyn":
        return False
    if m == "Kailyn" and n != "Peter":
        return False

    # 2. Dragonfruit not in house 4
    if house == 4 and s == "dragonfruit":
        return False

    # 3. iPhone13 person is artist (checked later when both phone and occ known)
    # 4. mother Aniya is Arnold
    if n == "Arnold" and m != "Aniya":
        return False
    if m == "Aniya" and n != "Arnold":
        return False

    # 5. mother Aniya is Desert smoothie
    if m == "Aniya" and s != "desert":
        return False
    if s == "desert" and m != "Aniya":
        # desert could be elsewhere, but only house with mother Aniya must be desert.
        # We allow other deserts only if mother Aniya already assigned elsewhere.
        pass

    # 6. mother Aniya is in house 2
    if house == 2 and m != "Aniya":
        return False
    if m == "Aniya" and house != 2:
        return False

    # 7. Lime smoothie is in house 1
    if house == 1 and s != "lime":
        return False
    if s == "lime" and house != 1:
        return False

    # 8. Huawei P50 person is doctor (checked later)
    # 9. Eric drinks Lime smoothies
    if n == "Eric" and s != "lime":
        return False
    if s == "lime" and n != "Eric":
        return False

    # 10. One house between teacher and Bob (checked after full assignment)

    # 11. mother Aniya is lawyer
    if m == "Aniya" and o != "lawyer":
        return False
    if o == "lawyer" and m != "Aniya":
        # other lawyers could exist? No, each occupation unique, so this ensures only Arnold is lawyer.
        pass

    # 12. iPhone13 person likes Cherry smoothies (checked later)

    # 13. Arnold uses OnePlus 9
    if n == "Arnold" and p != "oneplus 9":
        return False
    if p == "oneplus 9" and n != "Arnold":
        return False

    # 14. doctor is mother Penny
    if o == "doctor" and m != "Penny":
        return False
    if m == "Penny" and o != "doctor":
        return False

    # 15. Peter uses Samsung Galaxy S21
    if n == "Peter" and p != "samsung galaxy s21":
        return False
    if p == "samsung galaxy s21" and n != "Peter":
        return False

    # 16. Bob is not in house 3
    if n == "Bob" and house == 3:
        return False

    # 17. mother Holly directly left of Peter
    if m == "Holly":
        # Peter must be in house+1
        peter_house = next((h for h, name in state["name"].items() if name == "Peter"), None)
        if peter_house is not None and peter_house != house + 1:
            return False
    if n == "Peter":
        # mother Holly must be in house-1
        holly_house = next((h for h, mom in state["mother"].items() if mom == "Holly"), None)
        if holly_house is not None and holly_house != house - 1:
            return False

    # Additional cross‑checks that can be evaluated early:
    # iPhone13 ↔ artist ↔ cherry
    if p == "iphone 13":
        if o != "artist" or s != "cherry":
            return False
    if o == "artist":
        if p != "iphone 13" or s != "cherry":
            return False
    if s == "cherry":
        if p != "iphone 13" or o != "artist":
            return False

    # Huawei ↔ doctor
    if p == "huawei p50":
        if o != "doctor":
            return False
    if o == "doctor":
        if p != "huawei p50":
            return False

    return True


def final_checks(state):
    # 10. One house between teacher and Bob
    teacher_house = next(h for h, occ in state["occ"].items() if occ == "teacher")
    bob_house = next(h for h, name in state["name"].items() if name == "Bob")
    if abs(teacher_house - bob_house) != 2:
        return False

    # 17 already enforced partially; ensure exact adjacency now
    peter_house = next(h for h, name in state["name"].items() if name == "Peter")
    holly_house = next(h for h, mom in state["mother"].items() if mom == "Holly")
    if holly_house != peter_house - 1:
        return False

    return True


def solve():
    # initial empty state
    state = {
        "name": {},
        "phone": {},
        "smoothie": {},
        "mother": {},
        "occ": {},
    }

    # remaining pools
    remaining = {
        "name": set(names),
        "phone": set(phones),
        "smoothie": set(smoothies),
        "mother": set(mothers),
        "occ": set(occupations),
    }

    solution = None

    def backtrack(house):
        nonlocal solution
        if solution is not None:
            return
        if house > 5:
            if final_checks(state):
                # store solution copy
                solution = {
                    k: dict(v) for k, v in state.items()
                }
            return

        # iterate over possible assignments for this house
        for n in list(remaining["name"]):
            # quick name‑specific checks
            if n == "Peter" and "Kailyn" not in remaining["mother"]:
                continue
            if n == "Arnold" and "Aniya" not in remaining["mother"]:
                continue
            if n == "Eric" and "lime" not in remaining["smoothie"]:
                continue

            # choose mother
            for m in list(remaining["mother"]):
                # enforce name‑mother relations early
                if n == "Peter" and m != "Kailyn":
                    continue
                if n == "Arnold" and m != "Aniya":
                    continue
                if house == 2 and m != "Aniya":
                    continue
                if m == "Aniya" and house != 2:
                    continue
                if m == "Holly":
                    # Peter must be to the right; if Peter already placed, check adjacency
                    peter_house = next((h for h, name in state["name"].items() if name == "Peter"), None)
                    if peter_house is not None and peter_house != house + 1:
                        continue
                if n == "Peter":
                    # Holly must be left
                    holly_house = next((h for h, mom in state["mother"].items() if mom == "Holly"), None)
                    if holly_house is not None and holly_house != house - 1:
                        continue

                # choose smoothie
                for s in list(remaining["smoothie"]):
                    if house == 1 and s != "lime":
                        continue
                    if s == "lime" and house != 1:
                        continue
                    if house == 2 and s != "desert":
                        continue
                    if s == "desert" and m != "Aniya":
                        continue
                    if house == 4 and s == "dragonfruit":
                        continue
                    if n == "Eric" and s != "lime":
                        continue
                    if n == "Arnold" and s != "desert":
                        continue

                    # choose phone
                    for p in list(remaining["phone"]):
                        if n == "Peter" and p != "samsung galaxy s21":
                            continue
                        if n == "Arnold" and p != "oneplus 9":
                            continue
                        if p == "huawei p50":
                            # doctor will be enforced later
                            pass
                        if p == "iphone 13":
                            # must be artist and cherry
                            if s != "cherry":
                                continue
                        # choose occupation
                        for o in list(remaining["occ"]):
                            if n == "Arnold" and o != "lawyer":
                                continue
                            if m == "Aniya" and o != "lawyer":
                                continue
                            if o == "lawyer" and m != "Aniya":
                                continue
                            if o == "doctor" and m != "Penny":
                                continue
                            if m == "Penny" and o != "doctor":
                                continue
                            if p == "huawei p50" and o != "doctor":
                                continue
                            if o == "doctor" and p != "huawei p50":
                                continue
                            if o == "artist":
                                if p != "iphone 13" or s != "cherry":
                                    continue
                            if p == "iphone 13":
                                if o != "artist" or s != "cherry":
                                    continue
                            if s == "cherry":
                                if p != "iphone 13" or o != "artist":
                                    continue
                            if n == "Bob" and house == 3:
                                continue
                            # assign temporarily
                            state["name"][house] = n
                            state["mother"][house] = m
                            state["smoothie"][house] = s
                            state["phone"][house] = p
                            state["occ"][house] = o

                            # remove from pools
                            remaining["name"].remove(n)
                            remaining["mother"].remove(m)
                            remaining["smoothie"].remove(s)
                            remaining["phone"].remove(p)
                            remaining["occ"].remove(o)

                            if consistent(state, house):
                                backtrack(house + 1)

                            # restore pools
                            remaining["name"].add(n)
                            remaining["mother"].add(m)
                            remaining["smoothie"].add(s)
                            remaining["phone"].add(p)
                            remaining["occ"].add(o)

                            # delete temporary assignments
                            del state["name"][house]
                            del state["mother"][house]
                            del state["smoothie"][house]
                            del state["phone"][house]
                            del state["occ"][house]

                            if solution is not None:
                                return

    backtrack(1)

    if solution is None:
        print("No solution found", file=sys.stderr)
        sys.exit(1)

    # Print in required format
    for h in range(1, 6):
        print(
            f"House {h}: {solution['name'][h]}, {solution['phone'][h]}, "
            f"{solution['smoothie'][h]}, {solution['mother'][h]}, {solution['occ'][h]}"
        )


if __name__ == "__main__":
    solve()

