import itertools

names = ["Bob", "Peter", "Eric", "Alice", "Arnold"]
children = ["Timothy", "Meredith", "Fred", "Bella", "Samantha"]

# Fixed child assignments from clues
fixed_child = {
    "Eric": "Timothy",
    "Bob": "Fred",
    "Peter": "Meredith",
}

# Remaining children to assign to remaining names
remaining_names = [n for n in names if n not in fixed_child]
remaining_children = [c for c in children if c not in fixed_child.values()]

def satisfies(pos, child_of):
    # pos: dict name -> house number (1..5)
    # child_of: dict name -> child

    # Clue 1: Eric (mother of Timothy) is directly left of the person whose child is Meredith (Peter)
    if pos["Eric"] + 1 != pos["Peter"]:
        return False

    # Clue 3: Samantha is somewhere to the right of Meredith
    # Find who has Samantha
    name_samantha = next(n for n, c in child_of.items() if c == "Samantha")
    if pos[name_samantha] <= pos["Peter"]:
        return False

    # Clue 4: Bob is directly left of Arnold
    if pos["Bob"] + 1 != pos["Arnold"]:
        return False

    # Clue 5: Meredith is somewhere to the right of Fred
    # Meredith -> Peter, Fred -> Bob
    if pos["Peter"] <= pos["Bob"]:
        return False

    return True

# Iterate over all permutations of positions (assign each name a distinct house 1..5)
for perm in itertools.permutations(range(1, 6), len(names)):
    pos = dict(zip(names, perm))

    # Early pruning using positional constraints that don't involve children
    if pos["Eric"] + 1 != pos["Peter"]:
        continue
    if pos["Bob"] + 1 != pos["Arnold"]:
        continue
    if pos["Peter"] <= pos["Bob"]:
        continue

    # Assign remaining children
    for child_perm in itertools.permutations(remaining_children):
        child_of = fixed_child.copy()
        child_of.update(dict(zip(remaining_names, child_perm)))

        if satisfies(pos, child_of):
            # Build house -> (name, child) mapping for output
            house_info = {pos[name]: (name, child_of[name]) for name in names}
            for house in range(1, 6):
                name, child = house_info[house]
                print(f"House {house}: {name}, {child}")
            raise SystemExit

