    if pos('genre', 'romance') is not None and pos('genre', 'fantasy') is not None:
        if pos('genre', 'romance') >= pos('genre', 'fantasy'):
            return False

    #25. lilies in house 2 (index 1)
    if pos('flower', 'lilies') is not None and pos('flower', 'lilies') != 1:
        return False

    #26. iris right of green color
    if pos('flower', 'iris') is not None and pos('color', 'green') is not None:
        if pos('flower', 'iris') <= pos('color', 'green'):
            return False

    return True

# ----- backtracking search -----
def solve():
    # pre‑compute all permutations (as tuples of house indices 0‑5)
    all_perms = list(itertools.permutations(range(6)))

    # order of categories to assign
    categories = [
        ('name', names),
        ('hair', hairs),
        ('color', colors),
        ('phone', phones),
        ('flower', flowers),
        ('genre', genres)
    ]

    # state holds dicts: category -> {value: house}
    state = {}

    def backtrack(idx):
        if idx == len(categories):
            # complete solution found
            return state

        cat, values = categories[idx]
        for perm in all_perms:
            # build a copy of state with this category added
            new_state = {k: dict(v) for k, v in state.items()}
            new_state[cat] = {}
            make_pos(new_state[cat], values, perm)

            if constraints_ok(new_state):
                result = backtrack(idx + 1)
                if result is not None:
                    return result
        return None

    return backtrack(0)

solution = solve()
if solution is None:
    sys.exit('No solution found')

# ----- produce output -----
# Build reverse look‑ups: house -> attribute
house_attrs = []
for house in range(6):
    # find each attribute belonging to this house
    name = next(n for n, p in solution['name'].items() if p == house)
    flower = next(f for f, p in solution['flower'].items() if p == house)
    genre = next(g for g, p in solution['genre'].items() if p == house)
    phone = next(ph for ph, p in solution['phone'].items() if p == house)
    hair = next(h for h, p in solution['hair'].items() if p == house)
    color = next(c for c, p in solution['color'].items() if p == house)
    house_attrs.append((name, flower, genre, phone, hair, color))

for i, attrs in enumerate(house_attrs, start=1):
    print(f'House {i}: {", ".join(attrs)}')

