animals = ["fish", "rabbit", "bird", "cat", "horse", "dog"]
musics = ["classical", "hip hop", "country", "jazz", "rock", "pop"]
cigars = ["prince", "dunhill", "blends", "pall mall", "blue master", "yellow monster"]

# ---------- helper ----------
def pos_of(arr, val):
    """return index of val in arr or None if not placed yet"""
    try:
        return arr.index(val)
    except ValueError:
        return None

# ---------- constraints ----------
def check_constraints(names_arr, books_arr, smoothies_arr,
                      animals_arr, musics_arr, cigars_arr):
    # 1. blends <=> fantasy
    if (pos_of(cigars_arr, "blends") is not None) != (pos_of(books_arr, "fantasy") is not None):
        return False
    if (p := pos_of(cigars_arr, "blends")) is not None:
        if books_arr[p] != "fantasy":
            return False
    if (p := pos_of(books_arr, "fantasy")) is not None:
        if cigars_arr[p] != "blends":
            return False

    # 2. biography <=> desert
    if (p := pos_of(books_arr, "biography")) is not None:
        if smoothies_arr[p] != "desert":
            return False
    if (p := pos_of(smoothies_arr, "desert")) is not None:
        if books_arr[p] != "biography":
            return False

    # 3. two houses between pop and country -> distance 3
    if (p := pos_of(musics_arr, "pop")) is not None and (c := pos_of(musics_arr, "country")) is not None:
        if abs(p - c) != 3:
            return False

    # 4. rabbit in third house (index 2)
    if animals_arr[2] is not None and animals_arr[2] != "rabbit":
        return False
    if pos_of(animals_arr, "rabbit") not in (None, 2):
        return False

    # 5. Arnold -> bird
    if (p := pos_of(names_arr, "Arnold")) is not None:
        if animals_arr[p] != "bird":
            return False
    if (p := pos_of(animals_arr, "bird")) is not None:
        if names_arr[p] != "Arnold":
            return False

    # 6. country music in fifth house (index 4)
    if musics_arr[4] is not None and musics_arr[4] != "country":
        return False
    if pos_of(musics_arr, "country") not in (None, 4):
        return False

    # 7. mystery not in first house (index 0)
    if books_arr[0] == "mystery":
        return False
    if pos_of(books_arr, "mystery") == 0:
        return False

    # 8. lime not in third house
    if smoothies_arr[2] == "lime":
        return False
    if pos_of(smoothies_arr, "lime") == 2:
        return False

    # 9. fish right of rock music
    if (f := pos_of(animals_arr, "fish")) is not None and (r := pos_of(musics_arr, "rock")) is not None:
        if not (f > r):
            return False

    #10. prince left of cherry smoothie
    if (p := pos_of(cigars_arr, "prince")) is not None and (c := pos_of(smoothies_arr, "cherry")) is not None:
        if not (p < c):
            return False

    #11. Bob -> cat
    if (p := pos_of(names_arr, "Bob")) is not None:
        if animals_arr[p] != "cat":
            return False
    if (p := pos_of(animals_arr, "cat")) is not None:
        if names_arr[p] != "Bob":
            return False

    #12. Eric -> cherry smoothie
    if (p := pos_of(names_arr, "Eric")) is not None:
        if smoothies_arr[p] != "cherry":
            return False
    if (p := pos_of(smoothies_arr, "cherry")) is not None:
        if names_arr[p] != "Eric":
            return False

    #13. yellow monster in sixth house (index5)
    if cigars_arr[5] is not None and cigars_arr[5] != "yellow monster":
        return False
    if pos_of(cigars_arr, "yellow monster") not in (None,5):
        return False

    #14. prince <=> dragonfruit
    if (p := pos_of(cigars_arr, "prince")) is not None:
        if smoothies_arr[p] != "dragonfruit":
            return False
    if (p := pos_of(smoothies_arr, "dragonfruit")) is not None:
        if cigars_arr[p] != "prince":
            return False

    #15. Carol directly left of Arnold
    if (c := pos_of(names_arr, "Carol")) is not None and (a := pos_of(names_arr, "Arnold")) is not None:
        if not (c + 1 == a):
            return False

    #16. blue master directly left of classical music
    if (b := pos_of(cigars_arr, "blue master")) is not None and (c := pos_of(musics_arr, "classical")) is not None:
        if not (b + 1 == c):
            return False

    #17. classical <=> historical fiction
    if (p := pos_of(musics_arr, "classical")) is not None:
        if books_arr[p] != "historical fiction":
            return False
    if (p := pos_of(books_arr, "historical fiction")) is not None:
        if musics_arr[p] != "classical":
            return False

    #18. dunhill next to science fiction
    if (d := pos_of(cigars_arr, "dunhill")) is not None and (s := pos_of(books_arr, "science fiction")) is not None:
        if abs(d - s) != 1:
            return False

    #19. horse directly left of Peter
    if (h := pos_of(animals_arr, "horse")) is not None and (p := pos_of(names_arr, "Peter")) is not None:
        if not (h + 1 == p):
            return False

    #20. watermelon <=> cat
    if (w := pos_of(smoothies_arr, "watermelon")) is not None:
        if animals_arr[w] != "cat":
            return False
    if (c := pos_of(animals_arr, "cat")) is not None:
        if smoothies_arr[c] != "watermelon":
            return False

    #21. blends directly left of jazz
    if (b := pos_of(cigars_arr, "blends")) is not None and (j := pos_of(musics_arr, "jazz")) is not None:
        if not (b + 1 == j):
            return False

    #22. cat in first house (index0) – already handled by fixed placement

    #23. desert <=> jazz
    if (d := pos_of(smoothies_arr, "desert")) is not None:
        if musics_arr[d] != "jazz":
            return False
    if (j := pos_of(musics_arr, "jazz")) is not None:
        if smoothies_arr[j] != "desert":
            return False

    #24. lime directly left of fish
    if (l := pos_of(smoothies_arr, "lime")) is not None and (f := pos_of(animals_arr, "fish")) is not None:
        if not (l + 1 == f):
            return False

    #25. blue master not in fifth house (index4)
    if cigars_arr[4] == "blue master":
        return False
    if pos_of(cigars_arr, "blue master") == 4:
        return False

    return True

# ---------- initial state ----------
N = 6
names_arr = [None]*N
books_arr = [None]*N
smoothies_arr = [None]*N
animals_arr = [None]*N
musics_arr = [None]*N
cigars_arr = [None]*N

# apply obvious fixed placements
animals_arr[2] = "rabbit"          # clue 4
musics_arr[4] = "country"         # clue 6
cigars_arr[5] = "yellow monster"  # clue13
animals_arr[0] = "cat"            # clue22
smoothies_arr[0] = "watermelon"   # clue20 (cat <=> watermelon)
names_arr[0] = "Bob"              # clue11 (Bob is cat lover)

# remaining value sets
def remaining(all_vals, arr):
    return [v for v in all_vals if v not in arr]

# ---------- backtracking ----------
def backtrack(pos):
    if pos == N:
        # all houses assigned, final check
        if check_constraints(names_arr, books_arr, smoothies_arr,
                             animals_arr, musics_arr, cigars_arr):
            # print solution
            for i in range(N):
                out = f"House {i+1}: {names_arr[i]}, {books_arr[i]}, {smoothies_arr[i]}, {animals_arr[i]}, {musics_arr[i]}, {cigars_arr[i]}"
                print(out)
            sys.exit(0)
        return

    # if this house already has all attributes (unlikely), skip
    if all(x is not None for x in (names_arr[pos], books_arr[pos],
                                   smoothies_arr[pos], animals_arr[pos],
                                   musics_arr[pos], cigars_arr[pos])):
        backtrack(pos+1)
        return

    # generate candidate values for each still‑empty slot
    name_cands = [names_arr[pos]] if names_arr[pos] is not None else remaining(names, names_arr)
    book_cands = [books_arr[pos]] if books_arr[pos] is not None else remaining(books, books_arr)
    smooth_cands = [smoothies_arr[pos]] if smoothies_arr[pos] is not None else remaining(smoothies, smoothies_arr)
    animal_cands = [animals_arr[pos]] if animals_arr[pos] is not None else remaining(animals, animals_arr)
    music_cands = [musics_arr[pos]] if musics_arr[pos] is not None else remaining(musics, musics_arr)
    cigar_cands = [cigars_arr[pos]] if cigars_arr[pos] is not None else remaining(cigars, cigars_arr)

    for n in name_cands:
        if n in names_arr and names_arr[pos] != n:
            continue
        names_arr[pos] = n
        for b in book_cands:
            if b in books_arr and books_arr[pos] != b:
                continue
            books_arr[pos] = b
            for s in smooth_cands:
                if s in smoothies_arr and smoothies_arr[pos] != s:
                    continue
                smoothies_arr[pos] = s
                for a in animal_cands:
                    if a in animals_arr and animals_arr[pos] != a:
                        continue
                    animals_arr[pos] = a
                    for m in music_cands:
                        if m in musics_arr and musics_arr[pos] != m:
                            continue
                        musics_arr[pos] = m
                        for c in cigar_cands:
                            if c in cigars_arr and cigars_arr[pos] != c:
                                continue
                            cigars_arr[pos] = c
                            if check_constraints(names_arr, books_arr, smoothies_arr,
                                                 animals_arr, musics_arr, cigars_arr):
                                backtrack(pos+1)
                            cigars_arr[pos] = None
                        musics_arr[pos] = None
                    animals_arr[pos] = None
                smoothies_arr[pos] = None
            books_arr[pos] = None
        names_arr[pos] = None

# start search
backtrack(0)

# If we reach here, no solution was found
print("No solution")

