#!/usr/bin/env python3
import itertools

# ----- data ---------------------------------------------------------
names = ["Alice", "Eric", "Bob", "Arnold", "Carol", "Peter"]
hobbies = ["gardening", "painting", "knitting", "photography", "cooking", "woodworking"]
cars = ["chevrolet silverado", "toyota camry", "bmw 3 series",
        "ford f150", "honda civic", "tesla model 3"]
styles = ["ranch", "colonial", "victorian", "mediterranean", "craftsman", "modern"]

# helper to get position (1‑based) of a value in a tuple
def pos_of(tup, val):
    return tup.index(val) + 1

# ----- constraints that involve only one category --------------------
def valid_name_perm(p):
    # 11. Alice not in house 3
    if pos_of(p, "Alice") == 3:
        return False
    # 12 & 20. Peter not in house 4 nor 3
    if pos_of(p, "Peter") in (3, 4):
        return False
    # 5. Arnold not in house 4
    if pos_of(p, "Arnold") == 4:
        return False
    return True

def valid_style_perm(p, name_perm):
    # 3. ranch style person is Alice
    if pos_of(p, "ranch") != pos_of(name_perm, "Alice"):
        return False
    # 17. Carol left of ranch
    if pos_of(name_perm, "Carol") >= pos_of(p, "ranch"):
        return False
    return True

def valid_car_perm(p, name_perm):
    # 14. ford f150 is in house 2
    if pos_of(p, "ford f150") != 2:
        return False
    # 18. toyota camry owner is Bob
    if pos_of(name_perm, "Bob") != pos_of(p, "toyota camry"):
        return False
    # 10. toyota camry not in house 5
    if pos_of(p, "toyota camry") == 5:
        return False
    return True

def valid_hobby_perm(p, name_perm, car_perm, style_perm):
    # 7 & 19: knitting = toyota camry = modern
    if pos_of(p, "knitting") != pos_of(car_perm, "toyota camry"):
        return False
    if pos_of(p, "knitting") != pos_of(style_perm, "modern"):
        return False
    # 18 already guarantees the toyota owner is Bob, so knitting hobby belongs to Bob
    if pos_of(name_perm, "Bob") != pos_of(p, "knitting"):
        return False
    # 2: mediterranean style = cooking hobby
    if pos_of(style_perm, "mediterranean") != pos_of(p, "cooking"):
        return False
    # 13: colonial style = woodworking hobby
    if pos_of(style_perm, "colonial") != pos_of(p, "woodworking"):
        return False
    # 16: ranch style = chevrolet silverado
    if pos_of(style_perm, "ranch") != pos_of(car_perm, "chevrolet silverado"):
        return False
    return True

# ----- cross‑category constraints (checked after all four tuples are chosen) ----
def all_constraints(name, hobby, car, style):
    # 1. Arnold right of bmw owner
    if pos_of(name, "Arnold") <= pos_of(car, "bmw 3 series"):
        return False
    # 4. Victorian house right of Eric
    if pos_of(style, "victorian") <= pos_of(name, "Eric"):
        return False
    # 6. One house between tesla and gardening (distance 2)
    if abs(pos_of(car, "tesla model 3") - pos_of(hobby, "gardening")) != 2:
        return False
    # 8. Bob right of Victorian house
    if pos_of(name, "Bob") <= pos_of(style, "victorian"):
        return False
    # 9. Two houses between gardening and Arnold (distance 3)
    if abs(pos_of(hobby, "gardening") - pos_of(name, "Arnold")) != 3:
        return False
    # 15. cooking and gardening adjacent
    if abs(pos_of(hobby, "cooking") - pos_of(hobby, "gardening")) != 1:
        return False
    # 21. photography adjacent to Peter
    if abs(pos_of(hobby, "photography") - pos_of(name, "Peter")) != 1:
        return False
    return True

# ----- search ---------------------------------------------------------
def solve():
    # pre‑filter permutations that already satisfy single‑category constraints
    name_perms = [p for p in itertools.permutations(names) if valid_name_perm(p)]
    style_perms = [p for p in itertools.permutations(styles)]
    car_perms = [p for p in itertools.permutations(cars)]
    hobby_perms = [p for p in itertools.permutations(hobbies)]

    for name in name_perms:
        # prune styles that depend on name (ranch & Carol)
        for style in (sp for sp in style_perms if valid_style_perm(sp, name)):
            for car in (cp for cp in car_perms if valid_car_perm(cp, name)):
                # hobby depends on name, car, style
                for hobby in (hp for hp in hobby_perms if valid_hobby_perm(hp, name, car, style)):
                    if all_constraints(name, hobby, car, style):
                        # found solution
                        for i in range(6):
                            house_no = i + 1
                            print(f"House {house_no}: {name[i]}, {hobby[i]}, {car[i]}, {style[i]}")
                        return

if __name__ == "__main__":
    solve()

