names = ["Eric", "Arnold", "Peter"]
phones = ["google pixel 6", "iphone 13", "samsung galaxy s21"]
animals = ["bird", "horse", "cat"]
occupations = ["doctor", "engineer", "teacher"]
months = ["jan", "sept", "april"]
lunches = ["grilled cheese", "pizza", "spaghetti"]

def satisfies(house_attrs):
    # unpack per house
    name = [h[0] for h in house_attrs]
    phone = [h[1] for h in house_attrs]
    animal = [h[2] for h in house_attrs]
    occupation = [h[3] for h in house_attrs]
    month = [h[4] for h in house_attrs]
    lunch = [h[5] for h in house_attrs]

    # Helper: index of a specific attribute value
    idx = lambda seq, val: seq.index(val)

    # 1. horse is directly left of teacher
    if idx(animal, "horse") + 1 != idx(occupation, "teacher"):
        return False

    # 2. spaghetti lunch → engineer
    for i in range(3):
        if lunch[i] == "spaghetti" and occupation[i] != "engineer":
            return False

    # 3. Samsung phone not in third house (index 2)
    if phone[2] == "samsung galaxy s21":
        return False

    # 4. doctor is cat lover
    for i in range(3):
        if occupation[i] == "doctor" and animal[i] != "cat":
            return False

    # 5. iPhone 13 user is Peter
    for i in range(3):
        if phone[i] == "iphone 13" and name[i] != "Peter":
            return False

    # 6. spaghetti lunch → January birthday
    for i in range(3):
        if lunch[i] == "spaghetti" and month[i] != "jan":
            return False

    # 7. Samsung phone → grilled cheese lunch
    for i in range(3):
        if phone[i] == "samsung galaxy s21" and lunch[i] != "grilled cheese":
            return False

    # 8. Samsung phone and Eric are neighbours
    if abs(idx(phone, "samsung galaxy s21") - idx(name, "Eric")) != 1:
        return False

    # 9. January birthday is to the right of September birthday
    if idx(month, "jan") <= idx(month, "sept"):
        return False

    return True

def main():
    # Iterate over all permutations of each attribute column
    for perm_names in itertools.permutations(names):
        for perm_phones in itertools.permutations(phones):
            for perm_animals in itertools.permutations(animals):
                for perm_occupations in itertools.permutations(occupations):
                    for perm_months in itertools.permutations(months):
                        for perm_lunches in itertools.permutations(lunches):
                            # Build list of house tuples (name, phone, animal, occupation, month, lunch)
                            houses = [
                                (perm_names[i],
                                 perm_phones[i],
                                 perm_animals[i],
                                 perm_occupations[i],
                                 perm_months[i],
                                 perm_lunches[i])
                                for i in range(3)
                            ]
                            if satisfies(houses):
                                # Print solution in required format
                                for idx, h in enumerate(houses, start=1):
                                    print(f"House {idx}: {', '.join(h)}")
                                return

if __name__ == "__main__":
    main()

